def esc(s): return s.replace('~','~0').replace('/','~1')
def props(doc,s,depth=0,prefix=''):
 if not isinstance(s,dict): return []
 if '$ref' in s: s=doc.get('components',{}).get('schemas',{}).get(s['$ref'].split('/')[-1],{})
 out=[]
 for k,v in (s.get('properties') or {}).items():
  out.append(prefix+k+':'+v.get('type','object' if '$ref' in v or 'properties' in v else 'unknown'))
  if depth<3 and isinstance(v,dict) and ('$ref' in v or 'properties' in v): out += props(doc,v,depth+1,prefix+k+'.')
  if depth<3 and isinstance(v,dict) and v.get('type')=='array' and isinstance(v.get('items'),dict): out += props(doc,v['items'],depth+1,prefix+k+'[].')
 return out
